//Credits
//Most of thd code either mine or heavily edited
//Inigo Quilez - https://iquilezles.org/articles/distfunctions/
//Simon Dev - https://youtu.be/BNZtUB7yhX4?si=BYa0fFE8p94YxVNp
//Kishimisu - https://youtu.be/khblXafu7iA?si=BrkA9si53tEGV13e

//Global vars
const int obj=3;
int steps=255;
float renderDist=100.;
vec3 skyColor = vec3(0.2,0.4,1);
vec3 sunDir = normalize(vec3(1,1,-1));
vec3 sunCol = vec3(0.8,0.9,0.1);

//Debug
bool ortho = false;
bool normalMaps = false;

//Sphere - Inigo Quilez https://iquilezles.org/articles/distfunctions/
float sdPie(vec3 p, float s) {
    return length(p)-s; 
}

//Rounded cube - Inigo Quilez https://iquilezles.org/articles/distfunctions/
float sdBox(vec3 p, vec3 b, float r) {
  vec3 q = abs(p) - b + r;

  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0) - r;
}

//“Terrain” - by me this time :)
float sdFloor(vec3 p) {
    return p.y;
}

vec2 minD(float [obj] array) {
    int i;
    float m = renderDist+1.;
    float sm = m;

    int iter;
    for (i=0; i<array.length(); i++) {
        m = min(m,array[i]);
        if (m<sm) {sm=m; iter=i;}
    }
    return vec2(sm,iter);
}

float [4] map(vec3 p) {
    vec3 [obj] C;
    C[0] = vec3(1,0.2,0.1);
    C[1] = vec3(0.2,0.9,0.9);
    C[2] = vec3(0.2 + 0.4 * mod(floor(p.x) + floor(p.z),2.));
    vec3 [obj] P;
    P[0] = vec3(sin(iTime)*3.,1,cos(iTime)*3.);
    P[1] = vec3(cos(iTime)*3.,sin(iTime)*3.,3) + vec3(P[0].xy,-1);
    P[2] = vec3(-2);
    float [obj] SD;
    SD[0] = sdPie(p-P[0],1.);
    SD[1] = sdBox(p-P[1],vec3(1),0.1);
    SD[2] = sdFloor(p-P[2]);

    vec2 m = minD(SD);

    float [4] ar;
    ar[0] = m.x;
    ar[1] = C[int(m.y)].r;
    ar[2] = C[int(m.y)].g;
    ar[3] = C[int(m.y)].b;
    return ar;
}

//Normals - Simon Dev https://youtu.be/BNZtUB7yhX4?si=BYa0fFE8p94YxVNp
vec3 calcNormal(vec3 p) {
    float e=0.001;
    vec3 v1 = vec3(map(p + vec3(e,0,0))[0],
                   map(p + vec3(0,e,0))[0],
                   map(p + vec3(0,0,e))[0]);

    vec3 v2 = vec3(map(p - vec3(e,0,0))[0],
                   map(p - vec3(0,e,0))[0],
                   map(p - vec3(0,0,e))[0]);

    return normalize(v1-v2);
}

vec3 cmyk(vec3 c) {
    float k=1.-min(min(c.r,c.b),min(c.b,c.g));
    float C=(1.-c.r-k)/(1.-k);
    float m=(1.-c.g-k)/(1.-k);
    float y=(1.-c.b-k)/(1.-k);
    return vec3(C,m,y);
}

float calcFog(in float t) {
    return clamp(pow(2.,t*0.02)-1.,0.,1.);
}

float calcAO( in vec3 pos, in vec3 nor )
{
	float occ = 0.0;
    float sca = 1.0;
    for( int i=0; i<5; i++ )
    {
        float h = 0.001 + 0.15*float(i)/4.0;
        float d = map( pos + h*nor )[0];
        occ += (h-d)*sca;
        sca *= 0.95;
    }
    return clamp( 1.0 - 1.5*occ, 0.0, 1.0 );    
}

//2D rotation matrix - Simon Dev https://youtu.be/BNZtUB7yhX4?si=BYa0fFE8p94YxVNp
mat2 rot2D(float angle) { //Standard 2d rotation matrix, have to swizzle to use it
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c,-s,s,c);
}

//Soft shadows - Inigo Quilez https://iquilezles.org/articles/rmshadows/
float softShadow( in vec3 ro, in vec3 rd, float mint, float maxt, float w )
{
    float res = 1.0;
    float t = mint;
    for( int i=0; i<256 && t<maxt; i++ )
    {
        float h = map(ro + t*rd)[0];
        res = min( res, h/(w*t) );
        t += clamp(h, 0.0, 0.5);
        if( res<-1.0 || t>maxt ) break;
    }
    res = max(res,-1.0);
    return 0.25*(1.0+res)*(1.0+res)*(2.0-res);
}

vec3 calcSky(in vec3 rd, in float minSunRad, in float maxSunRad) {
    vec3 oc = skyColor;
    float sunDot = dot(sunDir,rd);
    oc *= vec3((1.+dot(rd,sunDir))/2.+(1./3.));
    if (sunDot > minSunRad) { //Sun fade in
           float mixFactor = (sunDot-minSunRad)/(maxSunRad-minSunRad); //Sun fade function
           return mix(oc,sunCol,smoothstep(0.,1.,mixFactor));
           if (sunDot > maxSunRad) return sunCol; //The sun (my eyes!) 
    }
    return oc;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Pixel coordinates (from -1 to 1)
    vec2 uv = (fragCoord*2.-iResolution.xy)/iResolution.y;

    // Mouse coordinates (from -1 to 1)
    vec2 m = (iMouse.xy * 2. - iResolution.xy)/iResolution.y;

    // Time varying pixel color
    //vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    vec3 ro = vec3(0,0,-3);
    vec3 rd = normalize(vec3(uv,1));
    if (ortho) {
        ro = vec3(uv*6.,-3);
        rd = normalize(vec3(0,0,1));
    }

    if (iMouse.xy != vec2(0)) {
    ro.yz *= rot2D(-m.y*2.);
    rd.yz *= rot2D(-m.y*2.);

    ro.xz *= rot2D(-m.x*2.);
    rd.xz *= rot2D(-m.x*2.);
    }


    bool isSky = true;

    vec3 col = vec3(0.5);
    vec3 norm = vec3(0);
    vec3 cmykNorm = norm;

    int i;
    float t=0.;
    float shad;
    float ao;
    for (i=0; i<steps; i++) {
        vec3 pos = ro + rd * t;

        float [4] mD = map(pos);

        float d = mD[0];

        t+=d;

        if (d<0.01) {
            col = vec3(mD[1],
            mD[2],
            mD[3]);
            //Lighting - Inigo Quilez https://www.shadertoy.com/view/lsKcDD
            norm = calcNormal(pos);
            if (normalMaps) cmykNorm = normalize(cmyk(norm)); //For normal debug
            isSky = false;
            shad = clamp(dot(norm,sunDir), 0.0, 1.0 )*softShadow(pos,sunDir,0.01, 15.0, 0.05);
            vec3 hal = normalize(sunDir-rd);
            float spec = /*pow(clamp(dot(norm, hal),0.0,1.0),16.0)*/
                    shad *
                   (0.04+0.96*pow(clamp(1.0+dot(hal,rd),0.0,1.0),5.0));
            ao = calcAO(pos,norm);
            float amb = clamp( 0.5+0.5*norm.y, 0.0, 1.0 );
            col += amb*vec3(0.0,0.08,0.1);
            col += 12.0*spec*vec3(1.00,0.70,0.5);
            col *= ao;
            break;
        }
        if (t>renderDist) {
            isSky = true;
            break;
        }
    }
    vec3 light = vec3(pow(clamp(dot(sunDir,norm),0.,1.),1.));

    //Gamma correction
    col = pow(col,vec3(0.4545));

    //light = mix(light, vec3(0.5),0.4);
    col *= light;
    col *= shad;
    col = mix(col, col = calcSky(rd, 0.96, 0.997), calcFog(t));
    if (isSky) {
        col = calcSky(rd, 0.96, 0.99997);
    }
    //col += vec3(i)/float(steps);
    if (normalMaps) {
        col = norm;
        if (norm.r<0.||norm.g<0.||norm.b<0.) {
            col = cmykNorm;
        }
    }
    //Output to screen
    fragColor = vec4(col,1);
}
